fix.code:
// Việc CPU-bound chạy trên pool platform thread có giới hạn
private final ExecutorService cpuPool =
        Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

@GetMapping("/reports/{id}")
Report export(@PathVariable long id) throws Exception {
    // request vẫn chạy trên virtual thread, chỉ chờ kết quả
    return cpuPool.submit(() -> renderReport(id)).get(30, TimeUnit.SECONDS);
}
